from gurobipy import GRB, Model

def f():
    # Create the model
    model = Model("Traveling_Salesman")

    # Define the distances between cities
    distances = {
        (1, 2): 9, (1, 3): 16, (1, 4): 11, (1, 5): 9,
        (2, 1): 9, (2, 3): 9, (2, 4): 14, (2, 5): 9,
        (3, 1): 16, (3, 2): 9, (3, 4): 12, (3, 5): 18,
        (4, 1): 11, (4, 2): 14, (4, 3): 12, (4, 5): 5,
        (5, 1): 9, (5, 2): 9, (5, 3): 18, (5, 4): 5
    }

    # Add variables
    x = {}
    for i in range(1, 6):
        for j in range(1, 6):
            if i != j:
                x[i, j] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

    # Add constraints
    # Each city is visited exactly once
    for i in range(1, 6):
        model.addConstr(sum(x[i, j] for j in range(1, 6) if i != j) == 1, name=f"out_{i}")
        model.addConstr(sum(x[j, i] for j in range(1, 6) if i != j) == 1, name=f"in_{i}")

    # The route starts and ends at city 1
    model.addConstr(sum(x[1, j] for j in range(2, 6)) == 1, name="start")
    model.addConstr(sum(x[j, 1] for j in range(2, 6)) == 1, name="end")

    # The route does not visit the same city twice
    u = {}
    for i in range(1, 6):
        u[i] = model.addVar(vtype=GRB.INTEGER, name=f"u_{i}")
    for i in range(2, 6):
        for j in range(2, 6):
            if i != j:
                model.addConstr(u[i] - u[j] + 5 * x[i, j] <= 4, name=f"no_subtours_{i}_{j}")

    # Set objective
    model.setObjective(sum(distances[i, j] * x[i, j] for i in range(1, 6) for j in range(1, 6) if i != j), GRB.MAXIMIZE)

    # Optimize/solve the model
    model.optimize()

    # Print the optimized route
    route = [1]
    current_city = 1
    for _ in range(4):
        for j in range(1, 6):
            if j != current_city and x[current_city, j].x > 0.5:
                route.append(j)
                current_city = j
                break
    route.append(1)
    print("Optimized route:", ",".join(map(str, route)))

    # Return the optimized model
    return model
