        (5, 1): 8, (5, 2): 24, (5, 3): 18, (5, 4): 7
    }

    # Add variables
    x = {}
    for i in range(1, 6):
        for j in range(1, 6):
            if i != j:
                x[i, j] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

    # Add constraints
    # Each city is visited exactly once
    for i in range(1, 6):
        model.addConstr(sum(x[i, j] for j in range(1, 6) if i != j) == 1, name=f"out_{i}")
        model.addConstr(sum(x[j, i] for j in range(1, 6) if i != j) == 1, name=f"in_{i}")

    # The route forms a cycle
    u = {}
    for i in range(1, 6):
        u[i] = model.addVar(vtype=GRB.INTEGER, name=f"u_{i}")
    for i in range(2, 6):
        for j in range(2, 6):
            if i != j:
                model.addConstr(u[i] - u[j] + 5 * x[i, j] <= 4, name=f"cycle_{i}_{j}")

    # Set objective
    model.setObjective(sum(distances[i, j] * x[i, j] for i in range(1, 6) for j in range(1, 6) if i != j), GRB.MAXIMIZE)

    # Optimize/solve the model
    model.optimize()

    # Return the optimized model
    return model

