if model.status == GRB.OPTIMAL:
    x = model.getVars()
    route = [1]
    current_city = 1
    for _ in range(4):
        for var in x:
            if var.varName.startswith(f"x_{current_city}") and var.x > 0.5:
                next_city = int(var.varName.split("_")[2])
                route.append(next_city)
                current_city = next_city
                break
    route.append(1)
    print("Route:", ",".join(map(str, route)))
    print("Distance:", model.objVal)
else:
    print("No solution found")
