    # Add constraints
    # Each representative can only be seated next to two other representatives
    for i in range(1, 7):
        model.addConstr(sum(x[i, j] for j in range(1, 7) if i != j) == 2, name=f"two_neighbors_{i}")

    # Each pair of representatives can only be seated next to each other once
    for i in range(1, 7):
